mapper.select:
SELECT COUNT(*)
FROM post
WHERE id = #{postId}

SELECT COUNT(*)
FROM favorite
WHERE user_id = #{userId}
  AND post_id = #{postId}
  AND deleted_at IS NULL

mapper.update:
UPDATE favorite
SET deleted_at = #{deletedAt}
WHERE user_id = #{userId}
  AND post_id = #{postId}
  AND deleted_at IS NULL

mapper.select:
SELECT COUNT(*)
FROM favorite f
JOIN post p ON f.post_id = p.id
WHERE f.user_id = #{userId}
  AND f.deleted_at IS NULL

  AND p.type = #{type}

SELECT f.post_id, p.type, p.leaf_category_id, p.l2_category_id, p.title, p.price, p.price_unit, p.completeness_level, p.status, p.status_reason, p.created_at, f.created_at AS favorite_at FROM favorite f JOIN post p ON f.post_id = p.id WHERE f.user_id = #{userId} AND f.deleted_at IS NULL
AND p.type = #{type}
ORDER BY f.created_at DESC, f.id DESC LIMIT #{offset}, #{limit}
